   * holder's pid; a lock whose holder on this host is gone is stale and taken over, and so is an unreadable lock
   * untouched for OPERATION_LOCK_UNREADABLE_GRACE_MS (its holder died mid-write). Takeover is serialised through a
   * kernel-owned guard and unlinks only the file that was judged stale, so two resumers cannot both take it.
   * Returns the release function.
   * Assumptions: the unreadable-lock rule compares the lock file's mtime with this process's clock, so it holds on one
   * host and one filesystem (NFS, or clock skew beyond the grace, can take a live lock over early). The stale takeover
   * depends on the `flock` utility (/usr/bin/flock); without it a stale lock fails closed with a manual-removal message.
   */
  acquire(id: string): () => void {
    const lockPath = path.join(this.manager.getBaseDir(), `${id}.lock`);
    // The start time tells this holder from a later process that was given the same pid.
    const create = () => fs.writeFileSync(lockPath, JSON.stringify({ pid: process.pid, host: os.hostname(), at: new Date().toISOString(), startTicks: processStartTicks(process.pid) }), { flag: "wx" });
    const locked = (holder: { pid?: number; host?: string }) =>
      new OperationLockedError(`Operation ${id} is already being driven by pid ${holder.pid ?? "?"} on ${holder.host ?? "?"} (lock ${lockPath}).`);
    try {
      create();
    } catch (err: any) {
      if (err?.code !== "EEXIST") throw err;
      const judged = this.judgeLock(lockPath);
      if (!judged.stale) throw locked(judged.holder);
      let guard: FileGuard | null;
      try {
        guard = acquireFileGuard(`${lockPath}.reclaim`, { label: "Operation lock reclaim guard" });
      } catch (guardError) {
        throw new OperationLockedError(`Operation ${id} has a stale lock at ${lockPath} that cannot be taken over safely here (${(guardError as Error).message}); remove it by hand once no nexus command is using this workspace.`);
      }
      if (!guard) throw locked(judged.holder);
      try {
        operationLockSeams.afterStaleCheck?.();
        const now = this.judgeLock(lockPath, false);
        if (!now.stale || now.ino !== judged.ino || now.mtimeNs !== judged.mtimeNs) throw locked(now.holder);
        fs.unlinkSync(lockPath);
        try {
          create();
        } catch (createError: any) {
          if (createError?.code === "EEXIST") throw locked({});
          throw createError;
        }
      } finally {
        releaseFileGuard(guard);
      }
    }
    return () => {
      try {
        if (JSON.parse(fs.readFileSync(lockPath, "utf-8")).pid === process.pid) fs.rmSync(lockPath, { force: true });
      } catch {
        reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_release_failed");
      }
    };
  }

  private judgeLock(lockPath: string, report = true): { stale: boolean; holder: { pid?: number; host?: string; at?: string; startTicks?: string }; ino?: bigint; mtimeNs?: bigint } {
    let stat: fs.BigIntStats;
    try {
      stat = fs.lstatSync(lockPath, { bigint: true });
    } catch {
      return { stale: false, holder: {} };
    }
    let holder: { pid?: number; host?: string; at?: string; startTicks?: string } | undefined;
    try {
      const parsed = JSON.parse(fs.readFileSync(lockPath, "utf-8"));
      if (parsed && typeof parsed === "object") holder = parsed;
    } catch {
      if (report) reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_read_failed");
    }
    const identity = { ino: stat.ino, mtimeNs: stat.mtimeNs };
    if (!holder) return { stale: Date.now() - Number(stat.mtimeNs / 1_000_000n) > OPERATION_LOCK_UNREADABLE_GRACE_MS, holder: {}, ...identity };
    // A lock written before this host last booted is stale even if its pid has since been reused.
    const beforeBoot = holder.at !== undefined && Date.parse(holder.at) < Date.now() - os.uptime() * 1000;
    // A live pid whose start time differs from the recorded one is another process: the holder is gone. A lock
    // without a start time (an older build wrote it), or a host where it cannot be read, is judged on the pid alone.
    const startedNow = holder.pid !== undefined && typeof holder.startTicks === "string" ? processStartTicks(holder.pid) : undefined;
    const reused = startedNow !== undefined && startedNow !== holder.startTicks;
    const stale = holder.host === os.hostname() && (beforeBoot || holder.pid === undefined || !processAlive(holder.pid) || reused);
    return { stale, holder, ...identity };
  }

  /** Returns the live lock holder for an operation, or undefined when there is no readable live lock by another process. */
  activeLock(id: string): { pid?: number; host?: string; at?: string } | undefined {
    const lockPath = path.join(this.manager.getBaseDir(), `${id}.lock`);
    const judged = this.judgeLock(lockPath, false);
    if (judged.stale || judged.holder.pid === undefined) return undefined;
    if (judged.holder.pid === process.pid) return undefined;
    return judged.holder;
  }

  /** Most recently updated operation in this workspace that can resume after restart. */
  latestResumable(): DurableOperationState | undefined {
    return this.list().find((op) => op.status === "WAITING" || op.status === "RUNNING" || op.status === "PAUSED");
  }

  /**
   * Keeps the record this build is about to upgrade, once. Refuses to overwrite an existing copy whose bytes differ:
   * an earlier migration already produced it, and silently replacing it would destroy the only v1 evidence.
   */
  private backupBeforeMigration(id: string, fromVersion: unknown): void {
    const record = path.join(this.manager.getBaseDir(), `${id}.json`);
    const backup = `${record}.pre-migration-v${String(fromVersion)}`;
    let bytes: Buffer;
    try {
      bytes = fs.readFileSync(record);
    } catch (error: any) {
      // The record was just read to decide this backup was needed; its absence is a real problem, not a reason to skip.
      throw new Error(`Operation ${id}: cannot read ${record} to keep a pre-migration copy (${String(error?.message ?? error)})`);
    }
    if (fs.existsSync(backup)) {
      const existing = fs.readFileSync(backup);
      if (!existing.equals(bytes)) {
        throw new Error(
          `Operation ${id}: cannot migrate the operation record because ${backup} already exists with different content. ` +
            `Move it aside to continue, or restore it to read the record with the build that wrote it.`,
        );
      }
      return;
    }
    writePrivateFile(backup, bytes, { durable: true, mode: 0o600 });
  }
}

